# First aid guides (English source). Each guide: id, icon, category, title, subtitle, keywords, blocks.
# Blocks: ("p", text) ("h", heading) ("ul", [items]) ("ol", [steps]) ("w", warning)
G = [
("aid-cpr", "aid", "Survival", "CPR: when someone is not breathing", "Chest compressions save lives",
 "cpr resuscitation cardiac arrest heart not breathing unconscious compressions",
 [("p", "If a person does not respond and is not breathing normally, their heart has probably stopped. Every minute without CPR lowers the chance of survival."),
  ("ol", ["Check the area is safe for you.", "Shout and tap the shoulders. No answer and no normal breathing (gasping does not count)? Start now.", "Call 112 on speaker, or send someone. Ask for a defibrillator (AED) if there is one nearby.", "Kneel beside the chest. Heel of one hand in the centre of the chest, other hand on top.", "Push hard and fast: 5-6 cm deep, 100-120 times a minute. Let the chest rise fully between pushes.", "If trained and willing: after 30 compressions give 2 rescue breaths. If not, do compressions only without stopping.", "Do not stop until help arrives, the person wakes up and breathes normally, or you are physically exhausted."]),
  ("w", "Compressions only are much better than doing nothing. In a remote place, keep going and swap with others every 2 minutes.")]),
("aid-recovery", "aid", "Survival", "Recovery position", "Unconscious but breathing",
 "recovery position unconscious breathing side vomit airway",
 [("p", "An unconscious person lying on their back can choke on their tongue or vomit. If they breathe normally, turn them on their side."),
  ("ol", ["Kneel beside them. Put the arm nearest you at a right angle, palm up.", "Bring the far arm across the chest and hold the back of that hand against their near cheek.", "Bend the far knee up, foot flat on the ground.", "Pull on the far knee to roll them towards you onto their side.", "Tilt the head back slightly so the airway stays open and the mouth points down.", "Keep them warm, call 112 and check breathing every minute."]),
  ("w", "If you suspect a spine injury (fall from height, high speed), move them only if they vomit or you must leave them, and keep head and body in line.")]),
("aid-choking", "aid", "Survival", "Choking", "Back blows and abdominal thrusts",
 "choking choke food stuck throat heimlich airway cough",
 [("p", "If the person can cough, speak or breathe, encourage them to keep coughing. Act only if they cannot breathe, speak or cough."),
  ("ol", ["Stand beside and slightly behind them, support the chest and lean them forward.", "Give up to 5 sharp blows between the shoulder blades with the heel of your hand.", "If that fails, stand behind them, fist just above the belly button, other hand over it, and pull sharply inwards and upwards up to 5 times.", "Alternate 5 back blows and 5 thrusts.", "If they become unconscious, call 112 and start CPR."]),
  ("w", "After abdominal thrusts the person must be checked by a doctor, even if they feel fine.")]),
("aid-bleeding", "aid", "Survival", "Severe bleeding", "Press hard and do not let go",
 "bleeding blood wound cut hemorrhage pressure bandage",
 [("p", "Heavy bleeding can kill in minutes. Your hands are the first tool."),
  ("ol", ["Protect yourself with gloves or a plastic bag if you can.", "Press firmly on the wound with a clean cloth, bandage or your hand.", "Keep pressing for at least 10 minutes without lifting to look.", "If blood soaks through, add more cloth on top and keep pressing.", "Wrap tightly with a bandage to keep the pressure.", "Lay the person down, keep them warm and call 112."]),
  ("w", "For bleeding from an arm or leg that does not stop with pressure, a tourniquet can save a life. See the tourniquet guide.")]),
("aid-tourniquet", "aid", "Survival", "Tourniquet", "Last resort for limb bleeding",
 "tourniquet bleeding arm leg amputation belt windlass",
 [("p", "Use a tourniquet only for life-threatening bleeding from an arm or leg that strong direct pressure cannot stop."),
  ("ol", ["Place it 5-8 cm above the wound, never on a joint.", "A commercial tourniquet is best. Improvised: a band at least 4 cm wide (scarf, triangular bandage), tied around the limb with a stick to twist it.", "Twist until the bleeding stops. It will hurt: that is normal.", "Secure the stick so it cannot unwind.", "Write the time it was applied on the skin or on tape.", "Do not loosen it. Call 112 and say a tourniquet is on."]),
  ("w", "Never use thin cord, wire or a narrow strap: they cut the skin and do not stop the bleeding.")]),
("aid-wound", "aid", "Survival", "Cleaning small wounds", "Stop infection before it starts",
 "wound cut scrape graze clean infection disinfect dressing",
 [("ul", ["Wash your hands first.", "Rinse the wound with plenty of drinking water: pressure helps wash out dirt.", "Remove small debris with clean tweezers.", "Cover with a clean dressing and change it daily.", "Signs of infection: growing redness, heat, swelling, pus, red streaks, fever."]),
  ("w", "See a doctor for deep wounds, animal bites, wounds that gape open, or if you are not vaccinated against tetanus.")]),
("aid-blisters", "aid", "Survival", "Blisters", "Stop them before they stop you",
 "blister feet foot hot spot boots socks",
 [("p", "A blister starts as a hot spot. Stop as soon as you feel rubbing."),
  ("ul", ["Hot spot: dry the skin, cover with tape or a blister plaster.", "Small intact blister: leave the skin on and protect it with a donut of padding.", "Large painful blister: clean, pierce at the edge with a sterilised needle, press the fluid out, keep the roof skin and cover.", "Change wet socks, keep laces even, cut toenails before the trip."]),
  ("w", "Watch for infection: redness spreading or pus.")]),
("aid-sprain", "aid", "Survival", "Sprained ankle", "Can you still walk out?",
 "sprain ankle twisted knee ligament swelling",
 [("ul", ["Stop, sit and check: can you bear weight for 4 steps? If not, it may be broken.", "Cool it with cold water or snow wrapped in cloth, 15 minutes at a time.", "Wrap with an elastic bandage in a figure of eight, not too tight.", "Raise the leg when resting.", "Walking poles take weight off; keep the boot on and laced firmly to support it."]),
  ("w", "Strong pain on the bone, deformity, or numb toes: treat as a fracture and call for help.")]),
("aid-fracture", "aid", "Survival", "Fractures and splints", "Keep it still",
 "fracture broken bone splint arm leg immobilize",
 [("ol", ["Do not try to straighten a deformed limb.", "Support it in the position you found it.", "Splint it: pad with clothing and fix it to something rigid (poles, sticks, a rolled sleeping mat) including the joints above and below.", "Check fingers or toes: they should stay warm and pink.", "Arm: a sling with a scarf or jacket. Leg: tie it to the other leg with padding between.", "Keep the person warm and call 112."]),
  ("w", "Open fracture (bone through the skin): cover with a clean dressing, do not push the bone back.")]),
("aid-head", "aid", "Survival", "Head injury", "When a bump becomes dangerous",
 "head injury concussion fall knock unconscious helmet",
 [("p", "After a blow to the head, watch the person closely for 24 hours."),
  ("ul", ["Call 112 if they were knocked out, even briefly.", "Danger signs: worsening headache, repeated vomiting, confusion, drowsiness, unequal pupils, fluid from the nose or ears, seizure, weakness of one side.", "Do not let them continue a difficult route.", "Keep them company and do not let them sleep alone that night."]),
  ("w", "With a fall from height, also suspect a neck injury: keep head and neck still.")]),
("aid-hypothermia", "cold", "Survival", "Hypothermia", "When the body gets too cold",
 "hypothermia cold shivering wet wind confusion",
 [("p", "Hypothermia can happen at 10 °C with wind and rain, not only in snow."),
  ("ul", ["Early signs: strong shivering, clumsy hands, bad mood, slow thinking.", "Severe signs: shivering stops, confusion, drowsiness. This is an emergency.", "Get out of wind and wet, into shelter.", "Replace wet clothing with dry layers, add a hat and insulation under them.", "Warm sweet drinks if they can swallow safely.", "Warm the chest, armpits and neck with warm (not hot) bottles or body heat."]),
  ("w", "Handle a severely hypothermic person very gently: rough movement can trigger heart rhythm problems. Call 112.")]),
("aid-frostbite", "cold", "Survival", "Frostbite", "Freezing of fingers, toes, nose and ears",
 "frostbite frozen fingers toes cold numb white",
 [("ul", ["Early stage (frostnip): skin white and numb, soft. Warm it with body heat: hands in armpits, feet on a partner's belly.", "Deep frostbite: skin hard, waxy, grey-white.", "Do not rub with snow or massage.", "Rewarm only if it will not freeze again: refreezing does much more damage.", "Rewarm in water at 37-39 °C (comfortable for an elbow) for 30 minutes.", "Do not burst blisters. Cover loosely, keep dry."]),
  ("w", "If you must walk out on frozen feet, it may be better to walk before rewarming. Get medical help.")]),
("aid-heat", "aid", "Survival", "Heat exhaustion and heatstroke", "Too hot can kill",
 "heat heatstroke exhaustion sun hot sweating dizzy",
 [("ul", ["Heat exhaustion: heavy sweating, weakness, headache, nausea, dizziness. Rest in shade, drink water with salts, cool the skin.", "Heatstroke: hot skin, confusion, strange behaviour, collapse. This is an emergency: call 112.", "Cool fast: wet the whole body, fan it, cold packs at neck, armpits and groin.", "Prevention: start early, rest in shade, drink regularly, wear a hat."]),
  ("w", "Do not give drinks to someone who is confused or drowsy: they may choke.")]),
("aid-sun", "aid", "Survival", "Sunburn and snow blindness", "Light is stronger up high",
 "sunburn snow blindness uv eyes sunglasses altitude",
 [("ul", ["UV increases about 10% every 1,000 m of altitude, and snow reflects up to 80%.", "Use sunscreen SPF 30-50 and reapply every 2 hours.", "Wear category 3-4 sunglasses on snow and glaciers, also when cloudy.", "Snow blindness: burning, gritty eyes hours later. Rest in the dark, cool compresses, no rubbing. It heals in 1-2 days.", "No sunglasses? Cut thin slits in cardboard or fabric to cover the eyes."])]),
("aid-altitude", "aid", "Survival", "Altitude sickness", "Climb high, sleep low",
 "altitude sickness mountain ams headache high hace hape acclimatize",
 [("p", "Above about 2,500 m many people get acute mountain sickness."),
  ("ul", ["Symptoms: headache plus nausea, tiredness, dizziness, poor sleep.", "Above 3,000 m, raise your sleeping altitude by no more than 300-500 m per day.", "Mild symptoms: stop climbing and rest until they go.", "Worsening symptoms: go down at least 300-500 m.", "Danger signs: confusion, loss of balance, breathlessness at rest, gurgling cough. Go down immediately and call for help."]),
  ("w", "Never climb higher with symptoms of altitude sickness.")]),
("aid-lightning", "weather", "Survival", "Struck by lightning", "Help them right away",
 "lightning struck strike thunderstorm burns cpr",
 [("p", "A person struck by lightning does not carry an electrical charge: you can touch them safely."),
  ("ul", ["Move to a safer place if the storm continues.", "If they are not breathing: start CPR immediately. Lightning victims often recover with fast CPR.", "Multiple victims: first help those who appear dead.", "Check for burns, fractures and hearing loss. Call 112."])]),
("aid-burns", "fire", "Survival", "Burns", "Cool water, 20 minutes",
 "burn burns fire scald hot water stove",
 [("ol", ["Stop the burning: smother flames, remove hot clothing unless stuck.", "Cool the burn under cool running or clean water for 20 minutes.", "Remove rings and watches before swelling.", "Cover loosely with cling film or a clean plastic bag.", "Keep the rest of the body warm."]),
  ("w", "Call 112 for burns larger than the person's hand, on the face, hands, feet or genitals, or if smoke was inhaled. No butter, oil or toothpaste.")]),
("aid-stings", "aid", "Survival", "Stings and allergic reactions", "Know anaphylaxis",
 "sting bee wasp hornet allergy anaphylaxis epipen swelling",
 [("ul", ["Bee sting: scrape the stinger out sideways with a fingernail or card.", "Cool the area. Antihistamine helps itching.", "Stings in the mouth or throat: suck ice and call 112.", "Anaphylaxis: swelling of face or tongue, difficulty breathing, hives, collapse. Call 112.", "If they have an adrenaline auto-injector, help them use it in the outer thigh, through clothing.", "Lay them down with legs raised, or sitting if breathing is hard."])]),
("aid-tick", "aid", "Survival", "Removing a tick", "Steady pull, the sooner the better",
 "tick removal lyme tbe encephalitis bite",
 [("ol", ["Use fine tweezers or a tick hook as close to the skin as possible.", "Pull straight out slowly and steadily, or twist with a tick hook.", "Do not squeeze the body, burn it or cover it with oil.", "Disinfect the spot and note the date.", "Watch for 30 days: an expanding red ring, fever or flu-like illness need a doctor."]),
  ("w", "In many Alpine areas ticks carry TBE (tick-borne encephalitis): ask your doctor about vaccination.")]),
("aid-bite", "aid", "Survival", "Animal bites", "Wash, cover, see a doctor",
 "bite dog animal fox bat rabies wound",
 [("ul", ["Wash the bite with soap and running water for 15 minutes.", "Cover with a clean dressing.", "See a doctor: animal bites easily get infected and may need antibiotics, tetanus or rabies vaccination.", "Bats, foxes and wild animals that behave strangely: always ask about rabies, even for a scratch."])]),
("aid-dehydration", "water", "Survival", "Dehydration", "Drink before you are thirsty",
 "dehydration thirst water urine salts electrolytes",
 [("ul", ["Signs: thirst, dark urine, headache, tiredness, dizziness when standing.", "On the trail drink about 0.5 l per hour, more in heat.", "Add salts on long hot days: a pinch of salt and sugar in water works.", "Pale yellow urine means you drink enough."]),
  ("w", "Drinking huge amounts of plain water for hours without salt can also be dangerous.")]),
("aid-diarrhea", "water", "Survival", "Diarrhoea on the trail", "Replace water and salt",
 "diarrhea diarrhoea stomach vomiting food water illness",
 [("ul", ["Drink small sips often: oral rehydration salts, or 1 l clean water with 6 teaspoons sugar and half a teaspoon salt.", "Eat plain food when you can.", "Wash hands with soap or gel before eating and after the toilet.", "See a doctor for blood in the stool, high fever, or if it lasts more than 3 days."])]),
("aid-eye", "aid", "Survival", "Something in the eye", "Rinse, do not rub",
 "eye dust grit foreign body rinse",
 [("ul", ["Do not rub.", "Rinse with plenty of clean water from the inner corner outward.", "Pull the upper lid over the lower one to sweep out grit.", "Anything stuck in the eye or chemicals: cover both eyes loosely and get help."])]),
("aid-nosebleed", "aid", "Survival", "Nosebleed", "Lean forward, pinch",
 "nosebleed nose bleeding",
 [("ul", ["Sit and lean forward, not back.", "Pinch the soft part of the nose for 10-15 minutes without letting go.", "Breathe through the mouth, spit out blood.", "If it lasts more than 30 minutes or follows a blow to the head, get help."])]),
("aid-sugar", "aid", "Survival", "Low blood sugar", "Fast sugar, then food",
 "hypoglycemia diabetes sugar low shaking sweating",
 [("ul", ["Signs: shaking, sweating, pale skin, hunger, confusion, strange behaviour.", "If they can swallow: give fast sugar (sweet drink, glucose tablets, sugar cubes).", "After 10-15 minutes, if better, give slower food like bread or a bar.", "If they are drowsy or cannot swallow: nothing by mouth, recovery position, call 112."])]),
("aid-asthma", "aid", "Survival", "Asthma attack", "Sit up, use the inhaler",
 "asthma breathing inhaler wheeze",
 [("ul", ["Help them sit up, leaning slightly forward. Stay calm.", "Help them use their reliever inhaler (usually blue): 1 puff every 30-60 seconds, up to 10 puffs.", "Call 112 if there is no improvement, they cannot speak in sentences or lips turn blue.", "Cold air and effort trigger attacks: a scarf over the mouth helps."])]),
]
